using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Windows.Forms;

namespace MacroExecute
{
    internal static class HeadlessUi
    {
        // Create hidden control handles for WM_PRINT, never Show/ShowDialog,
        // activate a window, register hotkeys, or pump global desktop input.
        private static void Prepare(Control control){var handle=control.Handle;control.PerformLayout();foreach(Control child in control.Controls)Prepare(child);}
        public static void Render(Form form,string path,bool preserveSelection=false){if(form.Visible)throw new InvalidOperationException("Headless render requires a hidden form.");Prepare(form);var main=form as MainForm;if(main!=null&&!preserveSelection)main.SelectHeadlessPreview();Prepare(form);form.PerformLayout();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));CompositeForms(form,form,bitmap);bitmap.Save(path,ImageFormat.Png);}if(form.Visible)throw new InvalidOperationException("Headless render made a window visible.");}
        private static void CompositeForms(Control parent,Form root,Bitmap destination)
        {
            foreach(Control child in parent.Controls){if(child.AccessibleName=="In-app dialog surface"){var location=InAppCoordinates.RelativeTo(child,root);using(var graphics=Graphics.FromImage(destination))using(var fill=new SolidBrush(child.BackColor))graphics.FillRectangle(fill,new Rectangle(location,child.Size));}if(child.AccessibleName=="In-app navigation menu"){using(var image=new Bitmap(Math.Max(1,child.Width),Math.Max(1,child.Height))){child.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));using(var graphics=Graphics.FromImage(destination))graphics.DrawImageUnscaled(image,InAppCoordinates.RelativeTo(child,root));}}var embedded=child as Form;if(embedded!=null&&!embedded.TopLevel){using(var image=new Bitmap(Math.Max(1,embedded.Width),Math.Max(1,embedded.Height))){embedded.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));var position=InAppCoordinates.RelativeTo(embedded,root);using(var graphics=Graphics.FromImage(destination))graphics.DrawImageUnscaled(image,position);}CompositeForms(embedded,root,destination);}else CompositeForms(child,root,destination);}
        }
        private static void ExpandExample(Control root){if(root.AccessibleName=="Toggle action example")typeof(Control).GetMethod("OnClick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(root,new object[]{EventArgs.Empty});foreach(Control child in root.Controls)ExpandExample(child);}
        private static bool PressNamed(Control root,string name){if(root.AccessibleName==name){typeof(Control).GetMethod("OnClick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(root,new object[]{EventArgs.Empty});return true;}foreach(Control child in root.Controls)if(PressNamed(child,name))return true;return false;}
        private static void VisualExample(string directory,ActionKind kind,string suffix="")
        {
            string name="visual-example-"+kind+suffix;
            using(var form=new StepEditor(new Step{Kind=kind},directory)){Render(form,Path.Combine(directory,name+"-settings.png"));foreach(Control child in form.Controls)ExpandExample(child);Render(form,Path.Combine(directory,name+".png"));if(kind==ActionKind.IfImage){PressNamed(form,"Example scenario: Image missing");Render(form,Path.Combine(directory,name+"-missing.png"));}form.Size=form.MinimumSize;Render(form,Path.Combine(directory,name+"-compact.png"));}
        }
        private static void AnimationFrames(string directory,ActionKind kind,int variant,string name)
        {
            string output=Path.Combine(directory,"animation-frames",name);Directory.CreateDirectory(output);
            using(var guide=new ActionShowcase(kind)){guide.Width=840;guide.Variant=variant;guide.Paused=true;for(int frame=0;frame<80;frame++){guide.Seek(frame*120);using(var bitmap=new Bitmap(guide.Width,guide.Height)){guide.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(output,frame.ToString("000")+".png"),ImageFormat.Png);}if(guide.AnimationRunning)throw new InvalidOperationException("Headless frame export started a playback timer.");}}
        }
        public static int ExportAnimationFrames(string directory)
        {
            Directory.CreateDirectory(directory);bool dark=UiTheme.Dark;string style=UiTheme.Style;
            try{UiTheme.Dark=true;UiTheme.Style="Aftershock";AnimationFrames(directory,ActionKind.IfImage,0,"if-image-found");AnimationFrames(directory,ActionKind.IfImage,1,"if-image-missing");AnimationFrames(directory,ActionKind.ClickImage,0,"click-image");AnimationFrames(directory,ActionKind.Repeat,0,"repeat");AnimationFrames(directory,ActionKind.Launch,0,"run-program");return 0;}finally{UiTheme.Dark=dark;UiTheme.Style=style;}
        }
        public static int Previews(string directory)
        {
            Directory.CreateDirectory(directory);bool original=UiTheme.Dark;var originalShortcuts=Shortcuts.Active;string originalStyle=UiTheme.Style;
            try{IconTests.Sheet(Path.Combine(directory,"icons-aftershock-dark.png"),"Aftershock",true);IconTests.Sheet(Path.Combine(directory,"icons-aftershock-light.png"),"Aftershock",false);foreach(string style in UiTheme.Styles)foreach(bool mode in new[]{false,true}){var prefs=new Preferences{AccentStyle=style,DarkMode=mode};using(var window=new MainForm(Samples.Nested(),null,false,false,true,prefs))Render(window,Path.Combine(directory,"palette-"+style.ToLowerInvariant()+"-"+(mode?"dark":"light")+".png"));using(var settings=new PreferencesForm(prefs))Render(settings,Path.Combine(directory,"preferences-"+style.ToLowerInvariant()+"-"+(mode?"dark":"light")+".png"));}foreach(bool dark in new[]{false,true}){var preferences=new Preferences{AccentStyle="Aftershock",DarkMode=dark};string suffix=dark?"dark":"light";using(var form=new MainForm(Samples.Nested(),null,false,false,true,preferences))Render(form,Path.Combine(directory,"workbench-"+suffix+".png"));using(var empty=new MainForm(new Macro(),null,false,false,true,preferences))Render(empty,Path.Combine(directory,"workbench-empty-"+suffix+".png"));using(var search=new MainForm(Samples.Nested(),null,false,false,true,preferences)){search.SearchHeadless("image");Render(search,Path.Combine(directory,"workbench-search-"+suffix+".png"));}UiTheme.Dark=dark;using(var editor=new StepEditor(Samples.Nested().Steps[0],directory))Render(editor,Path.Combine(directory,"image-editor-"+suffix+".png"));using(var shortcuts=new ShortcutForm(preferences.ActionShortcuts,preferences.HotkeyFiles,delegate{return null;}))Render(shortcuts,Path.Combine(directory,"shortcuts-"+suffix+".png"));using(var schedule=new ScheduleForm(delegate{return "Synthetic task";}))Render(schedule,Path.Combine(directory,"schedule-"+suffix+".png"));using(var settings=new PreferencesForm(preferences))Render(settings,Path.Combine(directory,"preferences-"+suffix+".png"));using(var picker=new WorkflowPicker(new[]{Path.GetFullPath(Path.Combine(directory,"..","examples","nested-image-if.mexec")),Path.GetFullPath(Path.Combine(directory,"..","examples","welcome.mexec")),Path.Combine(directory,"Moved workflow.mexec")},delegate{return null;}))Render(picker,Path.Combine(directory,"workflow-picker-"+suffix+".png"));using(var bindings=new WorkflowBindingsForm(new[]{Path.GetFullPath(Path.Combine(directory,"..","examples","welcome.mexec"))},preferences.ActionShortcuts,delegate{return null;}))Render(bindings,Path.Combine(directory,"workflow-bindings-"+suffix+".png"));}using(var form=new MainForm(Samples.Nested(),null,false,false,true,new Preferences{DarkMode=true,AccentStyle="Aftershock"}))Render(form,Path.Combine(directory,"workbench-aftershock.png"));UiTheme.Style="Aftershock";UiTheme.Dark=true;using(var clipboardEditor=new StepEditor(new Step{Kind=ActionKind.IfClipboard,ClipboardMatch=ClipboardMatchMode.All,Text="Document Type: Status Report\nMonthly Report\nStatus: Approved"},directory))Render(clipboardEditor,Path.Combine(directory,"clipboard-condition.png"));using(var copyEditor=new StepEditor(new Step{Kind=ActionKind.CopySelection},directory))Render(copyEditor,Path.Combine(directory,"clipboard-copy.png"));using(var rules=new StepEditor(new Step{Kind=ActionKind.IfClipboard,ClipboardMatch=ClipboardMatchMode.Rules,Text=ClipboardRuleTests.Example},directory)){Render(rules,Path.Combine(directory,"clipboard-row-rules.png"));rules.Size=rules.MinimumSize;Render(rules,Path.Combine(directory,"clipboard-row-rules-compact.png"));}using(var modifiedClick=new StepEditor(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer,MouseModifiers=MouseModifiers.Alt},directory))Render(modifiedClick,Path.Combine(directory,"modified-click.png"));using(var reference=new GuideCenter(ActionKind.IfImage))Render(reference,Path.Combine(directory,"guide-center.png"));using(var recipes=new GuideCenter()){recipes.SearchHeadless("nested");Render(recipes,Path.Combine(directory,"guide-recipes.png"));}foreach(ActionKind exampleKind in new[]{ActionKind.IfImage,ActionKind.ClickImage,ActionKind.Repeat,ActionKind.TypeText})VisualExample(directory,exampleKind);foreach(string guideStyle in UiTheme.Styles)foreach(bool guideDark in new[]{false,true}){UiTheme.Style=guideStyle;UiTheme.Dark=guideDark;VisualExample(directory,ActionKind.IfImage,"-"+guideStyle.ToLowerInvariant()+"-"+(guideDark?"dark":"light"));}UiTheme.Style="Aftershock";UiTheme.Dark=true;using(var shortcut=new KeyboardComposer())Render(shortcut,Path.Combine(directory,"keyboard-composer.png"));using(var launch=new StepEditor(new Step{Kind=ActionKind.Launch,Target="notepad.exe"},directory)){Render(launch,Path.Combine(directory,"launch-editor.png"));foreach(Control child in launch.Controls)ExpandExample(child);Render(launch,Path.Combine(directory,"launch-example.png"));}using(var timing=new StepEditor(new Step{Kind=ActionKind.Delay},directory))Render(timing,Path.Combine(directory,"timing-editor.png"));using(var review=new MacroReviewForm(MacroReview.Check(new Macro{Steps=new System.Collections.Generic.List<Step>{new Step{Kind=ActionKind.IfImage},new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.EndIf}}},directory)))Render(review,Path.Combine(directory,"macro-review.png"));using(var finder=new MainForm(Samples.Nested(),null,false,false,true)){Render(finder,Path.Combine(directory,"workbench-find.png"));finder.FindHeadless("image missing",0);Render(finder,Path.Combine(directory,"workbench-find.png"),true);}using(var emptyCompact=new MainForm(new Macro(),null,false,false,true,new Preferences{AccentStyle="Aftershock",DarkMode=true})){emptyCompact.Size=new Size(1000,650);Render(emptyCompact,Path.Combine(directory,"workbench-empty-compact.png"));}using(var compact=new MainForm(Samples.Nested(),null,false,false,true,new Preferences{AccentStyle="Aftershock",DarkMode=true})){compact.Size=new Size(1000,650);Render(compact,Path.Combine(directory,"workbench-compact.png"));}return 0;}finally{UiTheme.Dark=original;UiTheme.Style=originalStyle;Shortcuts.Active=originalShortcuts;}
        }
    }
}
